import boto3

def extract_fields(document_text):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Text': document_text},
        FeatureTypes=['FORMS'])
    fields = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = None
            value = None
            for child_block_id in block['ChildBlocks']:
                child_block = next(b for b in response['Blocks'] if b['Id'] == child_block_id['ChildId'])
                if child_block['BlockType'] == 'WORD':
                    if child_block['Relationships'][0]['Type'] == 'VALUE':
                        value = child_block['Text']
                    else:
                        key = child_block['Text']
            if key and value:
                fields[key] = value
    return fields

from typing import Any, Dict, List, Union

class OCRRequest:
    def __init__(self, document_path: str, language: str = 'en'):
        self.document_path = document_path
        self.language = language

class OCRResponse:
    def __init__(self, text: str, layout: Dict[str, Any]):
        self.text = text
        self.layout = layout

def normalize_text(text: str) -> str:
    return text.strip().lower()

def normalize_layout(layout: Dict[str, Any]) -> Dict[str, Any]:
    normalized_layout = {}
    for key, value in layout.items():
        normalized_layout[key.lower()] = value
    return normalized_layout

import boto3

class DocumentClient:
    def __init__(self, region_name='us-east-1'):
        self.client = boto3.client('textract', region_name=region_name)

    def analyze_document(self, document_bytes):
        response = self.client.analyze_document(
            Document={'Bytes': document_bytes},
            FeatureTypes=['TABLES', 'FORMS']
        )
        return response

import boto3

def extract_key_values(document_bytes):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS'])
    key_value_pairs = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = next((child['Text'] for child in block['Relationships'][0]['Ids'] if child['BlockType'] == 'WORD'), None)
            value = next((child['Text'] for child in block['Relationships'][1]['Ids'] if child['BlockType'] == 'WORD'), None)
            if key and value:
                key_value_pairs[key] = value
    return key_value_pairs

import boto3

def extract_tables(document_bytes):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES']
    )
    tables = []
    for table in response.get('Tables', []):
        table_data = {
            'Rows': [],
            'Columns': []
        }
        for row in table.get('Rows', []):
            row_data = []
            for cell in row.get('Cells', []):
                row_data.append(cell.get('Text', ''))
            table_data['Rows'].append(row_data)
        for column in table.get('Columns', []):
            column_data = []
            for cell in column.get('Cells', []):
                column_data.append(cell.get('Text', ''))
            table_data['Columns'].append(column_data)
        tables.append(table_data)
    return tables

import boto3

def extract_text(image_path):
    textract_client = boto3.client('textract')

    with open(image_path, 'rb') as document:
        image_bytes = document.read()

    response = textract_client.detect_document_text(
        Document={'Bytes': image_bytes}
    )

    text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text += item['Text'] + ' '
    return text
